                        exchange: staged.task.exchange,
                        rows_inserted: 0,
                        max_volume: 0,
                        message: debug.clone(),
                    });
                } else {
                    parsed_rows += parsed.rows.len();
                    parsed_files.push(parsed);
                }
            }
            Err(error) => {
                results.push(failed_download_result(
